"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["63394"],{9144(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.documento_exigido.geral_com_condicao","status":422,"titulo":"A exig\xeancia geral n\xe3o pode ter condi\xe7\xe3o de aplica\xe7\xe3o ativa"},"descricao":{"codigo":"uniplus.selecao.documento_exigido.geral_com_condicao","requisitos":["UNI-REQ-0057"],"oQueAconteceu":["Um documento `GERAL` \xe9 exigido de todos os candidatos, sem restri\xe7\xe3o. Uma condi\xe7\xe3o, ao\\ncontr\xe1rio, restringe o documento a quem satisfaz o que ela pede. As duas declara\xe7\xf5es se\\ncontradizem, e o sistema n\xe3o escolhe por conta pr\xf3pria qual delas vale.","A mensagem da resposta diz, na grava\xe7\xe3o: \\"A exig\xeancia \xe9 geral e n\xe3o pode ter condi\xe7\xe3o de\\naplica\xe7\xe3o ativa.\\" Na publica\xe7\xe3o, ela nomeia o tipo de documento: \\"A exig\xeancia \'*c\xf3digo do\\ntipo de documento*\' \xe9 geral e n\xe3o pode ter condi\xe7\xe3o de aplica\xe7\xe3o ativa.\\"","\xc9 uma confer\xeancia de forma, feita antes de o sistema consultar o tipo de documento, as fases ou\\nas demais configura\xe7\xf5es do processo. Ela examina as exig\xeancias na ordem recebida e para na\\nprimeira que tem defeito; dentro dessa exig\xeancia, os defeitos de forma aparecem juntos."],"comoResolver":["Se o documento \xe9 exigido de todos, retire as condi\xe7\xf5es dele. Se \xe9 exigido s\xf3 de quem satisfaz\\nas condi\xe7\xf5es, troque a aplicabilidade para `CONDICIONAL`.","Cuidado ao trocar para `CONDICIONAL` sem manter condi\xe7\xe3o alguma: uma exig\xeancia condicional sem\\ncondi\xe7\xf5es n\xe3o \xe9 exigida de ningu\xe9m, e a publica\xe7\xe3o a recusa quando ela \xe9 obrigat\xf3ria ou tem\\nconsequ\xeancia de indeferimento (ver\\n[`condicional_vazia_determina_resultado`](/erros/uniplus.selecao.documento_exigido.condicional_vazia_determina_resultado))."],"ondeAparece":["Defini\xe7\xe3o de documentos exigidos do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Documento exigido"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);